import type { storage_audit_config_schema } from '@config/schema'
import type { InventoryObject } from '@server/lib/oss-inventory'
import type { PoolConnection, RowDataPacket } from 'mysql2/promise'
import type { z } from 'zod'
import type { AuditPool } from './repository'
import { audit_destination, audit_key, create_audit_catalog } from './repository'

// Only immutable keys generated by current Content writers. Other namespaces
// lack the retirement/adoption protocol and remain advisory findings.
export const cleanup_key_pattern = '^content/att/(?:[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}|(?:staging|transfers|originals)/[a-f0-9]{32}/[a-f0-9]{32}|images/[a-f0-9]{32}/[a-f0-9]{32}\\.(?:avif|jpg))$'

interface Candidate extends RowDataPacket {
  id: number
  object_key: Buffer
  observed_size: number
  object_modified_at: Date
  cycle_id: string
}

export function create_orphan_cleanup(
  pool: AuditPool,
  storage: { find_object: (key: string) => Promise<InventoryObject | null> },
  destination: { bucket: string, endpoint: string },
  options: z.infer<typeof storage_audit_config_schema>,
  enqueue: (connection: PoolConnection, key: string) => Promise<void>,
) {
  const id = audit_destination(destination.bucket, destination.endpoint)
  const policy = options.orphanCleanup
  const eligible = `f.destination_id=? AND t.phase='completed' AND t.last_error_code IS NULL
    AND f.kind='orphan_candidate' AND f.resolved_at IS NULL AND f.last_seen_cycle=t.cycle_id
    AND f.observations>=? AND f.object_modified_at<=TIMESTAMPADD(SECOND,-?,CURRENT_TIMESTAMP(3))
    AND REGEXP_LIKE(CONVERT(f.object_key USING utf8mb4),?,'c')`
  const parameters = [id, policy.minObservations, policy.minAgeSeconds, cleanup_key_pattern]
  async function sweep(signal?: AbortSignal) {
    if (! options.enabled || ! policy.enabled || signal?.aborted)
      return
    const [rows] = await pool.execute<Candidate[]>(`SELECT f.id,f.object_key,f.observed_size,f.object_modified_at,t.cycle_id
      FROM storage_audit_findings f JOIN storage_audit_targets t ON t.destination_id=f.destination_id
      WHERE ${eligible} AND NOT EXISTS (SELECT 1 FROM content_object_retirements r WHERE r.object_key=f.object_key)
      ORDER BY f.id LIMIT ?`, [... parameters, options.batchSize])
    const deadline = Date.now() + options.batchBudgetMs
    for (const row of rows) {
      if (signal?.aborted || Date.now() >= deadline)
        break
      const key = audit_key(row.object_key)
      // Fresh metadata must still describe the exact observation. No cloud I/O
      // while holding the transaction or publication locks.
      const object = await storage.find_object(key)
      if (! object || object.size !== Number(row.observed_size)
        || object.modified_at.getTime() !== new Date(row.object_modified_at).getTime()
        || ! new RegExp(cleanup_key_pattern).test(key)) {
        continue
      }
      signal?.throwIfAborted()
      const connection = await pool.getConnection()
      try {
        await connection.beginTransaction()
        const [target] = await connection.execute<RowDataPacket[]>(`SELECT cycle_id FROM storage_audit_targets
          WHERE destination_id=? AND phase='completed' AND cycle_id=? AND last_error_code IS NULL FOR UPDATE`, [id, row.cycle_id])
        if (! target.length) {
          await connection.rollback()
          continue
        }
        // The tombstone locks out future adopters; rollback removes it when any
        // reference/workflow has appeared since the inventory. Scope 0 is global.
        await enqueue(connection, key)
        const [findings] = await connection.execute<RowDataPacket[]>(`SELECT f.id FROM storage_audit_findings f
          JOIN storage_audit_targets t ON t.destination_id=f.destination_id WHERE ${eligible}
          AND f.id=? AND f.observed_size=? AND f.object_modified_at=? FOR UPDATE`, [... parameters, row.id, object.size, object.modified_at])
        const [references] = await connection.execute<RowDataPacket[]>(`SELECT id FROM content_story_attachments
          WHERE object_key=? OR original_key=? OR avif_key=? OR jpeg_key=? OR redacted_avif_key=? OR redacted_jpeg_key=? LIMIT 1 FOR UPDATE`, [key, key, key, key, key, key])
        const catalog = create_audit_catalog(connection, destination, options.staticKeys)
        if (! findings.length || references.length || await catalog.reference(key) || await catalog.ownership(key, false)) {
          await connection.rollback()
          continue
        }
        signal?.throwIfAborted()
        await connection.commit()
      }
      catch (error) {
        await connection.rollback()
        throw error
      }
      finally { connection.release() }
    }
  }
  return { sweep }
}
